<script setup lang="ts">const route=useRoute();const{request}=useApi();const events=ref<any[]>([]);const loading=ref(true);const error=ref('');onMounted(async()=>{try{events.value=await request(`/campaigns/${route.params.id}/calendar`)}catch(e){error.value=e instanceof Error?e.message:'We could not load the calendar.'}finally{loading.value=false}})</script>
<template><section class="mx-auto max-w-7xl px-6 py-16"><h1 class="text-3xl font-bold">7-day calendar</h1><p v-if="loading" class="mt-6 text-cyan-300">Building your calendar…</p><p v-else-if="error" class="mt-6 rounded bg-red-950 p-3 text-red-200">{{error}}</p><CampaignCalendar v-else :events="events" class="mt-8" /></section></template>
